update public.learning_paths
set
  title = 'College Mathematics / Quantitative Reasoning',
  goal = 'College Mathematics / Quantitative Reasoning',
  summary = 'College Mathematics / Quantitative Reasoning builds the mathematical confidence and judgment needed for college, work, citizenship, and personal decisions. Students learn to estimate, model, interpret data, reason with probability, evaluate financial and public claims, communicate uncertainty, and critique quantitative arguments in the real world.',
  data = $cmqrjson${"slug": "college-mathematics-quantitative-reasoning", "title": "College Mathematics / Quantitative Reasoning", "description": "College Mathematics / Quantitative Reasoning builds the mathematical confidence and judgment needed for college, work, citizenship, and personal decisions. Students learn to estimate, model, interpret data, reason with probability, evaluate financial and public claims, communicate uncertainty, and critique quantitative arguments in the real world.", "topics": [{"id": "81e19263-e927-4440-9f96-d05c1e09278e", "type": "topic", "title": "Quantitative Literacy and Mathematical Habits of Mind", "description": "This opening section frames quantitative reasoning as a civic, professional, and personal survival skill. Students learn to approach numbers with curiosity, skepticism, and confidence rather than fear.", "children": [{"id": "c40dda3b-61af-435a-838e-5abed8932a29", "type": "subtopic", "title": "What Counts as Quantitative Reasoning", "children": [{"id": "57ee6a85-61a7-4fb3-b3b2-d0c946fd1d9c", "type": "concept", "title": "Numeracy, data literacy, modeling, and argument"}, {"id": "5d059c31-5f8f-40f0-b16a-e0c4f4c93f9c", "type": "concept", "title": "Exact answers versus useful approximations"}, {"id": "0e20da4c-2d14-4227-bfc5-c1297032f873", "type": "concept", "title": "Context, assumptions, and interpretation"}, {"id": "4bef0bc3-1930-4dab-ac8d-08fa87167cf0", "type": "concept", "title": "When a number is evidence and when it is noise"}], "description": "Students learn that quantitative reasoning is the use of numbers, patterns, evidence, and models to make sense of the world."}, {"id": "a7a73c33-9707-4165-8a89-c563688fb611", "type": "subtopic", "title": "Sense-Making and Estimation Culture", "children": [{"id": "29bb57cb-54e4-4a58-b7a6-1bcefdb660e8", "type": "concept", "title": "Order of magnitude thinking"}, {"id": "2d2a8126-7fc2-44fc-ac81-131d5a9e9834", "type": "concept", "title": "Back-of-the-envelope calculations"}, {"id": "e105d79d-cf75-45a4-9150-5a35e6d06f72", "type": "concept", "title": "Benchmarks and reference values"}, {"id": "bcdab557-601d-4af8-b514-7a95e43358df", "type": "concept", "title": "Explaining reasoning in words"}], "description": "The point is to check whether results are plausible before trusting a calculator or chart."}, {"id": "4d8f91f6-76d9-4bfe-9675-9d5a8e712c96", "type": "subtopic", "title": "Learning Math Strategically", "children": [{"id": "19cb7a4e-862f-4793-afa6-3542cded6132", "type": "concept", "title": "Worked examples and deliberate practice"}, {"id": "e048c608-09e9-49da-b5fd-62f6e4ea7090", "type": "concept", "title": "Error analysis and correction logs"}, {"id": "4efad36a-38f7-431e-aae0-3395d867b96c", "type": "concept", "title": "Multiple representations"}, {"id": "ea78fe2e-ec68-4061-9ea0-9f5581bda6de", "type": "concept", "title": "Study routines from A Mind for Numbers"}], "description": "Students build habits that make later problem-solving less brittle."}]}, {"id": "d8870811-adba-4b0f-982c-e262dfaf895d", "type": "topic", "title": "Numeracy, Estimation, Units, and Proportional Reasoning", "description": "This section teaches everyday number sense. Students practice moving between fractions, decimals, percentages, units, ratios, and real-world comparisons.", "children": [{"id": "2634cea7-5570-463d-bd5f-7e80dbb596e3", "type": "subtopic", "title": "Number Sense and Mental Math", "children": [{"id": "f4fe1fa4-f05a-466f-a8b9-f1770425fb78", "type": "concept", "title": "Fractions, decimals, percentages, and scientific notation"}, {"id": "5d00bde1-ff85-4fba-b095-c0e85501ec0a", "type": "concept", "title": "Rounding and significant figures"}, {"id": "094f8cef-b4ed-417f-b800-dc668b400572", "type": "concept", "title": "Unit conversions and dimensional analysis"}, {"id": "6ca26a49-67ab-4e29-bb44-8319205dcff9", "type": "concept", "title": "Absolute versus relative change"}], "description": "Students develop fluency with arithmetic that supports fast plausibility checks."}, {"id": "479c6c72-8ed8-4fbd-8d4a-bceab8488f23", "type": "subtopic", "title": "Ratios, Rates, and Proportions", "children": [{"id": "75a2cd76-2b11-46db-9535-a59ce8d2cc72", "type": "concept", "title": "Unit rates and per-capita comparisons"}, {"id": "892690eb-65bd-4678-a84d-3ab187fe1bde", "type": "concept", "title": "Scale factors and proportional relationships"}, {"id": "d2558a10-ce13-4da8-ae74-1c2a3ac174f3", "type": "concept", "title": "Index numbers and normalization"}, {"id": "658fd1ed-5e52-498d-a14e-01a6100a4859", "type": "concept", "title": "Common denominator thinking"}], "description": "Ratios and rates are the grammar of many public claims, from prices to health risks."}, {"id": "6d8d2300-e28b-4b58-a1d4-d8a6ea749752", "type": "subtopic", "title": "Estimation in Context", "children": [{"id": "f068ed27-2fdc-4834-9f18-d63e5b84b263", "type": "concept", "title": "Fermi problems"}, {"id": "1473a2b5-ff10-419d-8e43-ad88944639f5", "type": "concept", "title": "Bounds, assumptions, and scenarios"}, {"id": "8da4f619-9a66-4630-a2f0-d3da3e0f5ae2", "type": "concept", "title": "Checking calculator output"}, {"id": "8cc3ea2f-152d-4b1f-8e51-463f7f76df09", "type": "concept", "title": "Communicating uncertainty in estimates"}], "description": "Students learn to estimate quantities when exact data are unavailable or unnecessary."}]}, {"id": "4e94b7c4-a11d-4b10-b86f-21a9d2fe3a4f", "type": "topic", "title": "Algebra Review: Expressions, Equations, and Inequalities", "description": "Algebra is treated as a language for describing constraints and relationships. The aim is not symbolic manipulation for its own sake, but using algebra to represent real problems clearly.", "children": [{"id": "f4b27319-da09-41ca-aabc-3d683142ba74", "type": "subtopic", "title": "Expressions and Formulas", "children": [{"id": "bdd6b4ab-e132-41e6-b76d-d623e62b968d", "type": "concept", "title": "Variables, constants, terms, and coefficients"}, {"id": "af14d7f3-c84b-4282-9eec-a9fa28e350f5", "type": "concept", "title": "Substitution and evaluation"}, {"id": "af4fbfce-4181-4d40-97ca-a547a0e40619", "type": "concept", "title": "Rearranging formulas"}, {"id": "05a99cbc-6980-44f8-9669-ef786cc72012", "type": "concept", "title": "Interpreting units in formulas"}], "description": "Students learn to parse and evaluate formulas used in finance, science, and public information."}, {"id": "cef746ac-21a1-45a9-9153-62628c5c94a8", "type": "subtopic", "title": "Equations and Inequalities", "children": [{"id": "744d0fdf-0aeb-429f-afb6-65e2d981fdfb", "type": "concept", "title": "Linear equations and inequalities"}, {"id": "74213be2-4393-4142-849d-9778f8e437c2", "type": "concept", "title": "Systems of equations"}, {"id": "ccb9713e-dea3-4eca-a256-3a37d99fa7be", "type": "concept", "title": "Constraints and feasible values"}, {"id": "99c23e38-06fa-4847-a472-090d0db008ac", "type": "concept", "title": "Checking solutions in context"}], "description": "This subtopic reviews solving while emphasizing meaning."}, {"id": "64c059bc-34f1-4a30-af70-edb023754542", "type": "subtopic", "title": "Algebraic Modeling", "children": [{"id": "1b87b1ec-fb6b-459b-add1-96158d79ffb6", "type": "concept", "title": "Defining variables"}, {"id": "d8b8de86-86a2-49ec-a8ce-3cef8c4f8d82", "type": "concept", "title": "Building equations from assumptions"}, {"id": "3a9d414e-1e59-4d36-8493-52a87e466a18", "type": "concept", "title": "Comparing scenarios"}, {"id": "5543c12f-ac56-4cfe-84d8-ebcd265a4e77", "type": "concept", "title": "Sensitivity to assumptions"}], "description": "Students translate word problems into symbolic and tabular forms."}]}, {"id": "ecaf1247-8adf-45f8-a639-258caf1544ef", "type": "topic", "title": "Functions, Graphs, and Change", "description": "Functions help students describe relationships and change. This section connects tables, equations, graphs, and verbal descriptions.", "children": [{"id": "deb0a136-9dd8-49e5-8322-9097fd35e3f3", "type": "subtopic", "title": "Representing Relationships", "children": [{"id": "6a7c954d-f713-4aed-83d0-077e160e8b86", "type": "concept", "title": "Tables, graphs, formulas, and words"}, {"id": "89ac2980-da32-4140-a8e3-f5fc6ae794ea", "type": "concept", "title": "Independent and dependent variables"}, {"id": "b2387377-75a7-4673-9944-fca20a38560f", "type": "concept", "title": "Domain, range, and constraints"}, {"id": "d373b10f-2b7b-4678-b5cb-8d9f8cc28d81", "type": "concept", "title": "Function notation as naming, not mystery"}], "description": "Students learn to move between forms of the same relationship."}, {"id": "b9bf737a-cde5-43e4-aa8a-500357c0ab5b", "type": "subtopic", "title": "Reading Graphs Critically", "children": [{"id": "c22b0a01-e618-4446-a98b-2361c602c220", "type": "concept", "title": "Slope and intercepts"}, {"id": "9fc8561d-64e6-4bb7-aeb0-7c4e79a498c3", "type": "concept", "title": "Nonlinear shape and turning points"}, {"id": "78cdfac0-5ab9-4538-b33f-e6b421316774", "type": "concept", "title": "Axis manipulation and visual exaggeration"}, {"id": "d024eb50-032c-4299-87b9-e26d8643134f", "type": "concept", "title": "Graph choice and audience"}], "description": "Graphs persuade; students learn to read scales, axes, trends, and distortions."}, {"id": "b39830af-3694-410e-8e31-8619d9094619", "type": "subtopic", "title": "Rates of Change", "children": [{"id": "bb01da77-92d4-42ee-bd84-567be8453037", "type": "concept", "title": "Average rate of change"}, {"id": "a5688bf0-9e75-449a-b55f-8237e0442acb", "type": "concept", "title": "Slope as unit rate"}, {"id": "9db281a3-eab8-4a96-89d5-630fa875e5bb", "type": "concept", "title": "Increasing, decreasing, and constant relationships"}, {"id": "01cc6ef6-f743-40a0-806e-24f620ef0c37", "type": "concept", "title": "Interpreting change in context"}], "description": "Students use rates to describe motion, cost, growth, and social change."}]}, {"id": "48662570-3083-4218-8569-b3a7acdb60c9", "type": "topic", "title": "Linear, Exponential, and Logarithmic Models", "description": "This unit compares common models students encounter in finance, science, technology, population, and public debate. Students learn that choosing a model is a claim about how change works.", "children": [{"id": "ce428551-e2c8-4899-a6a7-c11219800455", "type": "subtopic", "title": "Linear Models", "children": [{"id": "f8dd0b62-5714-4c76-af43-c085136349cb", "type": "concept", "title": "Slope and intercept interpretation"}, {"id": "8cbd20ad-9030-488e-a4bd-773d960ffe39", "type": "concept", "title": "Break-even and cost-revenue models"}, {"id": "a2f31fab-b30f-4e00-850f-5571e375890d", "type": "concept", "title": "Linear trend lines"}, {"id": "ce1b6927-e0fc-40ae-b58c-f64ec12d7e1a", "type": "concept", "title": "Limits of extrapolation"}], "description": "Linear models are simple, useful, and often overused; students learn when they fit."}, {"id": "00599893-8c0b-4fbb-8534-3d6149a071ef", "type": "subtopic", "title": "Exponential Growth and Decay", "children": [{"id": "055390e1-28c2-4ca5-baec-abed71173ccb", "type": "concept", "title": "Percent growth and decay"}, {"id": "f3a9289d-9943-4228-9a1d-0e2791ca5368", "type": "concept", "title": "Doubling time and half-life"}, {"id": "dd3d141f-f3ce-4d71-ba33-90a509c6d4c6", "type": "concept", "title": "Compound interest and population growth"}, {"id": "1be0a256-ed05-4a3f-b981-f4fb7012213e", "type": "concept", "title": "Virality, inflation, and resource growth"}], "description": "Students examine growth processes where change compounds."}, {"id": "fa1482a1-c5a0-4632-94ed-c0c8de517e9f", "type": "subtopic", "title": "Logarithmic and Scale Models", "children": [{"id": "172613ca-e299-475e-beaa-6dc651dd30cf", "type": "concept", "title": "Log scales and orders of magnitude"}, {"id": "37da854a-c92a-4940-be46-a77f3d7d6a12", "type": "concept", "title": "pH, decibels, earthquakes, and information scale examples"}, {"id": "b187661f-ca14-477b-9c5d-a0509ef5ed97", "type": "concept", "title": "Interpreting charts with log axes"}, {"id": "78ba62f9-af53-444b-9fc0-acf4f34312b2", "type": "concept", "title": "When linear intuition fails"}], "description": "Students meet logarithms as tools for compressed scales and inverse exponential thinking."}]}, {"id": "899433af-1faf-401a-8740-fe232bd7c7be", "type": "topic", "title": "Geometry, Measurement, Scale, and Spatial Reasoning", "description": "This section grounds quantitative reasoning in space, design, maps, and measurement. Students use geometry for practical comparison rather than abstract proof alone.", "children": [{"id": "810d6ef7-9db9-4baf-811f-67695fd54358", "type": "subtopic", "title": "Measurement and Units", "children": [{"id": "10dcacbc-c935-4024-849c-7be329d04e1e", "type": "concept", "title": "Length, area, volume, density, and rates"}, {"id": "88d545bf-0058-409f-b191-339ebe48e9a3", "type": "concept", "title": "Metric and U.S. customary conversions"}, {"id": "dcbc29b9-8408-43d8-8afc-250f396882ab", "type": "concept", "title": "Precision, accuracy, and measurement error"}, {"id": "dfae3e85-9d49-46d4-8e0a-0ecb1ecb9aef", "type": "concept", "title": "Dimensional reasoning"}], "description": "Students learn how measurement choices affect conclusions."}, {"id": "b2a00f6a-1734-40ec-8a66-f2faa1c8f92e", "type": "subtopic", "title": "Geometry in Everyday Contexts", "children": [{"id": "1591516a-3b4e-4456-94d9-970976784ebb", "type": "concept", "title": "Perimeter, area, surface area, and volume"}, {"id": "e86f6991-7571-4f8d-995d-68022b4122ee", "type": "concept", "title": "Similarity, scale, and maps"}, {"id": "7841a65f-c051-460d-994f-4c6b268a9893", "type": "concept", "title": "Packaging, housing, materials, and layout examples"}, {"id": "a53298bc-2918-4db6-9dc4-c937a6959745", "type": "concept", "title": "Optimization by geometry"}], "description": "Students apply geometric formulas to real objects and situations."}, {"id": "96d57db5-e0a6-438a-8d3d-81a4edb70f2a", "type": "subtopic", "title": "Spatial Data and Maps", "children": [{"id": "19a155f2-8412-4579-971a-53a4878d8f5a", "type": "concept", "title": "Scale bars, projections, and distortion"}, {"id": "910410ae-997f-4982-8a64-38dca44deaff", "type": "concept", "title": "Density maps and choropleths"}, {"id": "135b6755-f85f-40d0-8ddb-a7042af01cf3", "type": "concept", "title": "Distance, accessibility, and service areas"}, {"id": "db2eddc9-6e50-4e55-8e82-980534aaa62a", "type": "concept", "title": "Geographic data ethics"}], "description": "Students interpret spatial visualizations with care."}]}, {"id": "3775aefc-cf57-495f-afb1-6c595b8c2a55", "type": "topic", "title": "Logic, Sets, and Argument Structure", "description": "Logic gives students tools for evaluating claims before numbers even appear. This unit supports clear reasoning in math, writing, debate, and decision-making.", "children": [{"id": "b8a74c6c-e739-4eab-b97d-7ad0576bc1bb", "type": "subtopic", "title": "Statements, Conditions, and Validity", "children": [{"id": "229cf223-fcf2-492d-9000-b7a304e36edf", "type": "concept", "title": "If-then statements"}, {"id": "8decf9dd-ee7e-4641-b12c-b43a281b18f1", "type": "concept", "title": "Necessary and sufficient conditions"}, {"id": "1c1de470-2019-4f5e-b242-1e57b97996f1", "type": "concept", "title": "Converse, inverse, and contrapositive"}, {"id": "11f18768-87da-4be0-8f2f-e8ee3983e2c6", "type": "concept", "title": "Validity versus truth"}], "description": "Students learn the structure of logical claims."}, {"id": "37cece45-71dd-4447-94bc-e25bf11d93fa", "type": "subtopic", "title": "Sets, Categories, and Counting Arguments", "children": [{"id": "9c0a5d93-39c0-497f-a592-9e1538213e12", "type": "concept", "title": "Sets, subsets, unions, intersections, and complements"}, {"id": "ca2c085b-bed9-432c-94d4-21f8570e3a26", "type": "concept", "title": "Venn diagrams"}, {"id": "0aa8aa19-ff27-4b12-a4cb-858ae211a1d3", "type": "concept", "title": "Inclusion-exclusion intuition"}, {"id": "ab0be6a4-6b5c-4f9d-a052-139854bd8b4b", "type": "concept", "title": "Classification errors and boundary cases"}], "description": "Students learn how categories shape conclusions."}, {"id": "3545e969-893f-4250-ab38-dad01f2275b5", "type": "subtopic", "title": "Fallacies and Quantitative Claims", "children": [{"id": "8dbeb46e-ce48-4a9c-ae70-55dcf3a9267b", "type": "concept", "title": "Correlation versus causation"}, {"id": "1e291d15-047b-4159-b70b-f8a75b724afa", "type": "concept", "title": "Base-rate neglect"}, {"id": "f06fb208-d8f2-4d94-a224-d94d20c73b73", "type": "concept", "title": "False precision"}, {"id": "eb9c1934-8cd3-473f-ad94-365f4e4f8abc", "type": "concept", "title": "Anecdote, cherry-picking, and misleading averages"}], "description": "Students identify reasoning traps in arguments that use numbers."}]}, {"id": "1b36bbb8-19de-4397-88b6-c1f72761cb5d", "type": "topic", "title": "Probability, Risk, and Counting", "description": "Probability helps students reason when outcomes are uncertain. The focus is interpretation, risk, and decision-making rather than long formula lists.", "children": [{"id": "c22eff9d-b85e-42c9-86ab-88d5cb778051", "type": "subtopic", "title": "Basic Probability Ideas", "children": [{"id": "b5ea7d58-1ba7-46b6-958d-50179552daa5", "type": "concept", "title": "Events, sample spaces, and probability rules"}, {"id": "a21c2a73-e85a-4297-ad20-6a0dff95bbb9", "type": "concept", "title": "Independent and dependent events"}, {"id": "a4b3db6c-cce1-472c-9509-1826cf6ba600", "type": "concept", "title": "Conditional probability"}, {"id": "c6dda629-1a9e-4ba1-a30c-491459b120bf", "type": "concept", "title": "Mutually exclusive versus overlapping events"}], "description": "Students learn the language of chance and uncertainty."}, {"id": "46d28415-5cd3-4c6f-92c6-d9b727c40ce9", "type": "subtopic", "title": "Counting and Expected Value", "children": [{"id": "67e31746-1ef9-44b4-886f-190309b7eeb4", "type": "concept", "title": "Combinations, permutations, and tree diagrams"}, {"id": "76effde5-eb31-4dce-aea7-34cca3a61dc1", "type": "concept", "title": "Expected value and long-run average"}, {"id": "a8fce07e-2f44-4f2e-9f5b-8af270b91981", "type": "concept", "title": "Games, lotteries, insurance, and warranties"}, {"id": "2d440f7f-0c4d-45cd-a55d-21f0532bbde4", "type": "concept", "title": "Risk preference and non-monetary consequences"}], "description": "Students learn simple counting tools and why expected value matters."}, {"id": "ec8ea448-6d02-4b0f-8036-60720ff02b3d", "type": "subtopic", "title": "Risk Communication", "children": [{"id": "fe2231e7-d240-4d34-bc01-dc3875bb2361", "type": "concept", "title": "Absolute and relative risk"}, {"id": "e1aacfc4-45d3-48ba-aa6c-0739b1e7fab8", "type": "concept", "title": "Odds, rates, and probabilities"}, {"id": "1f16351e-30fc-443b-b97a-2336174dc2ef", "type": "concept", "title": "False positives and screening tests"}, {"id": "80e4f90c-45c7-49b8-b5a7-dd92fb0c50a9", "type": "concept", "title": "Communicating uncertainty honestly"}], "description": "Students practice interpreting risk claims in health, finance, weather, and policy."}]}, {"id": "4f16c87c-6ad7-459e-be6b-3b3a7af9a20c", "type": "topic", "title": "Descriptive Statistics and Data Visualization", "description": "This unit teaches students to summarize and visualize data responsibly. The goal is to see both signal and variation.", "children": [{"id": "8f3e2547-f583-4060-b508-6ec75de86365", "type": "subtopic", "title": "Summaries of Center and Spread", "children": [{"id": "53026dfd-4ee7-4ba0-9db2-558d3ec7f068", "type": "concept", "title": "Mean, median, mode, and resistant summaries"}, {"id": "2e1b8a40-e6ae-497d-8da3-77ac291a5772", "type": "concept", "title": "Range, interquartile range, variance, and standard deviation"}, {"id": "87da199f-9932-4826-83e8-33ab2fc32fda", "type": "concept", "title": "Outliers and skew"}, {"id": "5e64609a-69b1-40dd-8546-b063b7a3efa1", "type": "concept", "title": "Choosing the right summary for the question"}], "description": "Students learn what different summaries reveal and hide."}, {"id": "3d3d013f-7cd4-4760-b72b-583aba0c0c66", "type": "subtopic", "title": "Distributions and Comparisons", "children": [{"id": "8b5d07e3-3239-489c-b2af-04e5ba4498b5", "type": "concept", "title": "Histograms, boxplots, dotplots, and density shapes"}, {"id": "6b853ccd-5d4b-4f7b-aed8-f8e915b0a058", "type": "concept", "title": "Normal distribution intuition"}, {"id": "e7743025-aa0e-48b3-bd59-a18327933ac9", "type": "concept", "title": "Percentiles and z-scores"}, {"id": "adf2cf0c-7e5f-4de1-bd17-089d6098fe69", "type": "concept", "title": "Comparing groups fairly"}], "description": "Students learn to compare groups, shapes, and variability."}, {"id": "0466217b-b60a-4f24-8dbc-f9680bb927ac", "type": "subtopic", "title": "Visualization Choices", "children": [{"id": "0395487d-4a07-4acf-9984-b9672c3a738f", "type": "concept", "title": "Bar charts, line charts, scatterplots, and maps"}, {"id": "6d9e3d47-733d-4b4c-b4bf-b7f319e723da", "type": "concept", "title": "Scales, baselines, labels, and color"}, {"id": "256dd526-3ef7-4f1e-acbf-05a1aa743e63", "type": "concept", "title": "Small multiples and dashboards"}, {"id": "f487ff9d-9de4-471c-a034-9ca236985b41", "type": "concept", "title": "Avoiding chartjunk and distortion"}], "description": "Students build charts that clarify instead of decorate."}]}, {"id": "87e302c5-24ae-480b-8b35-a1a1fc6b91d9", "type": "topic", "title": "Data Interpretation, Measurement, Bias, and Data Ethics", "description": "This section teaches students to ask where data came from and what it can legitimately support. Good quantitative reasoning begins before analysis.", "children": [{"id": "5440826f-34a0-4760-ad1c-f2209fb051b8", "type": "subtopic", "title": "Measurement and Operational Definitions", "children": [{"id": "c8b871e4-d0e4-4100-b120-bf4307c82e71", "type": "concept", "title": "What is being measured"}, {"id": "84b9ef78-29ca-457f-97bf-25496e16ce1d", "type": "concept", "title": "Proxy variables and hidden assumptions"}, {"id": "47b211a8-4589-4544-a6a0-5def74151437", "type": "concept", "title": "Reliability and validity"}, {"id": "a168a802-e045-461d-aed2-50e22816e06c", "type": "concept", "title": "Missing data and messy categories"}], "description": "Students learn that variables are constructed, not simply found."}, {"id": "acda4884-8193-4ca0-a127-452099921550", "type": "subtopic", "title": "Bias and Data Quality", "children": [{"id": "5c9094ec-4990-42da-8433-ca964db3fa1d", "type": "concept", "title": "Selection bias and survivorship bias"}, {"id": "13c8229e-0073-4396-adcf-9572e82c747a", "type": "concept", "title": "Response bias and measurement error"}, {"id": "4a088f65-d571-4dd0-bf15-bdd44d38c12b", "type": "concept", "title": "Confounding and omitted variables"}, {"id": "0503651c-7005-463a-9e41-27596a138872", "type": "concept", "title": "Outliers, duplicates, and data cleaning"}], "description": "Students identify common ways data can mislead."}, {"id": "772b525a-1fd5-477a-890e-1990c09783a9", "type": "subtopic", "title": "Ethics of Data Use", "children": [{"id": "697da9a9-4dc6-4acf-9e48-5a72872bf35a", "type": "concept", "title": "Privacy, consent, and identifiability"}, {"id": "e40e193f-7c24-494f-bcdc-d029baa47f8c", "type": "concept", "title": "Fairness and algorithmic bias"}, {"id": "b291695a-9307-4272-848f-6ea320f22e81", "type": "concept", "title": "Data visualization ethics"}, {"id": "72bd6f16-1d06-4ef2-b1a6-d06a75f6f7b4", "type": "concept", "title": "Uncertainty, humility, and responsible claims"}], "description": "Students examine power, privacy, and harm in quantitative work."}]}, {"id": "b7eb991d-5ebd-4328-9a4e-bddc74b0f5d5", "type": "topic", "title": "Sampling, Variability, and Introductory Inference", "description": "This unit introduces inference gently. Students learn why samples vary and why uncertainty belongs in conclusions.", "children": [{"id": "8ae8acdc-dbe0-4ac0-bf3c-80b8aa497675", "type": "subtopic", "title": "Sampling and Populations", "children": [{"id": "d2c41ddd-c3b7-41b4-a5c0-61da935d1472", "type": "concept", "title": "Random samples and convenience samples"}, {"id": "b64491b8-25af-4fd2-8b3a-de73c6a07131", "type": "concept", "title": "Sampling frames and nonresponse"}, {"id": "07720961-b066-4b0b-8460-175b31de394e", "type": "concept", "title": "Representative versus biased samples"}, {"id": "439d5622-2e47-417f-80e1-977ec76d53d9", "type": "concept", "title": "Survey wording and mode effects"}], "description": "Students learn the difference between sample information and population claims."}, {"id": "db92fa2a-cd07-4091-8047-14ab808a405b", "type": "subtopic", "title": "Sampling Variability", "children": [{"id": "41b8b173-ee71-443c-b4ab-719fa61f5bb8", "type": "concept", "title": "Simulation as intuition"}, {"id": "d39d0f9f-b102-4b0d-b0e7-56e9f4f94f39", "type": "concept", "title": "Law of large numbers"}, {"id": "139575cd-561c-48de-8610-ca0a478e98e5", "type": "concept", "title": "Central limit theorem as a practical idea"}, {"id": "cae0ccdc-fef6-4cde-8119-0f92bfbb2051", "type": "concept", "title": "Standard error and margin of error"}], "description": "This subtopic explains why different samples give different results."}, {"id": "35638f6e-1c9f-4cd8-a69d-dfea3fbded16", "type": "subtopic", "title": "Inference as Careful Claim-Making", "children": [{"id": "45287856-9a34-4e62-907a-4a578cad68fc", "type": "concept", "title": "Confidence intervals"}, {"id": "eb6da58c-0b08-49be-9d3e-3b71afd06457", "type": "concept", "title": "Hypothesis tests as evidence checks"}, {"id": "310b65bb-0abd-4c64-86bf-7a4a46338672", "type": "concept", "title": "P-values as one measure, not a verdict"}, {"id": "134d2597-fbce-4e15-aae0-15e3d89478b3", "type": "concept", "title": "Statistical significance versus practical importance"}], "description": "Students learn the meaning of confidence without overloading the course."}]}, {"id": "8619611b-8c17-4859-92d7-7a97ec8c4a58", "type": "topic", "title": "Financial Mathematics: Interest, Loans, Savings, Inflation, and Risk", "description": "This section makes quantitative reasoning immediately useful. Students learn to evaluate personal and public financial claims with mathematics.", "children": [{"id": "a0ef5a50-e178-426c-b5b3-d8eb5238be7e", "type": "subtopic", "title": "Interest and Compounding", "children": [{"id": "04c524bb-6ce6-48ba-9ed1-93d3d81e1796", "type": "concept", "title": "APR, APY, and compounding frequency"}, {"id": "a9125f02-ae40-478f-98a9-7576f9cb8532", "type": "concept", "title": "Savings, investments, and exponential growth"}, {"id": "df771db9-baa8-4da8-8b32-38cf165dfbc3", "type": "concept", "title": "Inflation and real purchasing power"}, {"id": "97597a1a-4814-4007-b7c1-ae29899c8df9", "type": "concept", "title": "Present value and future value intuition"}], "description": "Students compare simple and compound growth."}, {"id": "3ffe6adc-448e-4022-8eee-d45e49f2fe83", "type": "subtopic", "title": "Loans and Debt", "children": [{"id": "30e4bde8-d43b-48a4-85bc-22329a04ab23", "type": "concept", "title": "Amortization and payment formulas"}, {"id": "4656d4ed-d38c-4b77-93d2-5db6e7dd185e", "type": "concept", "title": "Credit cards, student loans, mortgages, and auto loans"}, {"id": "efdd274c-a942-426a-ad67-37e2bbb49edf", "type": "concept", "title": "Minimum payments and total cost"}, {"id": "fdc36062-8abb-4c25-a14e-020d164d1d2d", "type": "concept", "title": "Debt risk and affordability ratios"}], "description": "Students learn how borrowing works and why small rate differences matter."}, {"id": "abf504b8-3afd-448e-93d8-8949ad4a5c61", "type": "subtopic", "title": "Risk, Insurance, and Financial Decisions", "children": [{"id": "684f9cfb-ff2f-4777-b137-2d5bf15aaf09", "type": "concept", "title": "Emergency funds and risk pooling"}, {"id": "64187e41-7935-4558-bbf4-ab9290a1b382", "type": "concept", "title": "Insurance premiums and deductibles"}, {"id": "d73a45e6-e982-4f7e-90c3-0a5a3bae0f46", "type": "concept", "title": "Diversification intuition"}, {"id": "1e733e52-9d71-4f5a-a008-b39c43d4d2fa", "type": "concept", "title": "Scams, misleading rates, and behavioral traps"}], "description": "Students connect probability to financial planning."}]}, {"id": "12b0d7ab-dd27-4f0e-a349-a17d2c1efbc2", "type": "topic", "title": "Mathematical Modeling With Spreadsheets and Technology", "description": "This unit treats models as simplified stories about systems. Students learn to build transparent, editable models with assumptions visible.", "children": [{"id": "3a740746-d9d8-426e-a5eb-57979638708a", "type": "subtopic", "title": "Spreadsheet Fluency", "children": [{"id": "423f9b61-eeb0-4188-ac85-c61f5d47a1ae", "type": "concept", "title": "Cells, formulas, references, and fill patterns"}, {"id": "4a88b802-6a37-4c7b-8e93-3d5bc2b1b63e", "type": "concept", "title": "Tables, charts, and conditional formatting"}, {"id": "f087656d-7e56-40a2-89a5-a2b69da2539e", "type": "concept", "title": "Absolute and relative references"}, {"id": "da6e4f58-1ff9-4fb1-9c91-ff5767c0a06e", "type": "concept", "title": "Auditing formulas and avoiding hardcoded assumptions"}], "description": "Students learn a practical tool for repeated calculations and scenario analysis."}, {"id": "14e9d312-557e-4d26-8002-577d893d1421", "type": "subtopic", "title": "Model Building", "children": [{"id": "5335d0ba-0b6e-4196-a0ea-7bb68c70e6cf", "type": "concept", "title": "Inputs, outputs, parameters, and constraints"}, {"id": "722ecc4f-3f1a-45b4-8186-f7c0dbc5c347", "type": "concept", "title": "Linear, exponential, and piecewise models"}, {"id": "9608a153-9f1b-4c53-8ad6-34bef8e37951", "type": "concept", "title": "Scenario and sensitivity analysis"}, {"id": "a1f620f7-e37e-4a99-b1ac-3c950cef95c9", "type": "concept", "title": "Model limitations"}], "description": "Students translate a real situation into variables, assumptions, relationships, and outputs."}, {"id": "046dc1a6-c2a1-4796-a593-120da95e5d9a", "type": "subtopic", "title": "Simulation and Exploration", "children": [{"id": "7c6dc113-b7c2-4738-996e-c45fbbfa4e31", "type": "concept", "title": "Random number simulation"}, {"id": "a3efe8b3-f453-4ac2-b55e-1819d1373e07", "type": "concept", "title": "Monte Carlo intuition"}, {"id": "40619e60-a038-4436-882c-2097a0bc0211", "type": "concept", "title": "What-if tables"}, {"id": "30daf880-5e12-4df4-b062-234c628f3daf", "type": "concept", "title": "Visualizing model behavior"}], "description": "Students use technology to explore uncertainty and nonlinear outcomes."}]}, {"id": "47e61958-27d1-4fdc-8af0-756def63d868", "type": "topic", "title": "Decision-Making Under Uncertainty", "description": "Quantitative reasoning supports decisions, not just answers. This section teaches students to compare options under uncertainty and trade-offs.", "children": [{"id": "64d7cce0-2457-4ea5-8f84-dba161efea91", "type": "subtopic", "title": "Decision Trees and Expected Outcomes", "children": [{"id": "c8492db5-0bb0-42e5-8dba-baf614d199b6", "type": "concept", "title": "Options, outcomes, probabilities, and payoffs"}, {"id": "7356d3d8-7607-4e1d-9913-beea901e9877", "type": "concept", "title": "Expected value and expected utility intuition"}, {"id": "c3b360df-53e9-4b94-9c46-aa78a3e15544", "type": "concept", "title": "Regret and downside risk"}, {"id": "8542cc2f-d44e-4192-9936-4522addf5e0c", "type": "concept", "title": "Value of information"}], "description": "Students learn to structure decisions clearly."}, {"id": "e969e12a-a005-4523-826e-034ad222ef58", "type": "subtopic", "title": "Trade-Offs and Constraints", "children": [{"id": "329c8d1b-4516-4a4c-b129-42379eb1c890", "type": "concept", "title": "Cost-benefit thinking"}, {"id": "ad6f6da7-206a-4fac-83bc-7309d326190c", "type": "concept", "title": "Weighted scoring models"}, {"id": "15b6469e-71e2-4a24-a8d5-53b6bcc6779c", "type": "concept", "title": "Constraints, feasibility, and opportunity cost"}, {"id": "39a7a304-b4b5-4f62-8e44-a5e54f3607b9", "type": "concept", "title": "Sensitivity to assumptions"}], "description": "Students learn that decisions often involve multiple criteria."}, {"id": "463ed429-32f5-447a-ad7d-7a99fca8e82c", "type": "subtopic", "title": "Risk and Communication", "children": [{"id": "3a26c177-b06b-4db2-939a-4afec5db9d62", "type": "concept", "title": "Best case, base case, worst case"}, {"id": "7b0ddd58-e55d-46f6-9e7c-f3d0c6c956c5", "type": "concept", "title": "Ranges rather than false precision"}, {"id": "658c6d70-ed36-422a-8bea-90cadfc8ea7d", "type": "concept", "title": "Visual summaries for decisions"}, {"id": "db1a19b7-43d6-4fc3-af4c-8c4320923cb4", "type": "concept", "title": "Ethical limits of quantification"}], "description": "Students practice presenting recommendations with uncertainty intact."}]}, {"id": "d0fe7a99-fddf-40f2-86e7-58370aaea635", "type": "topic", "title": "Quantitative Arguments in Media, Science, and Public Policy", "description": "This unit helps students become better readers of the world. They learn to critique claims in news, advertising, policy, research, and social media.", "children": [{"id": "50afb287-74b4-4a5c-b980-32f368113b67", "type": "subtopic", "title": "Reading Quantitative Claims", "children": [{"id": "66b7cc87-955b-480b-bff4-06785ba86eeb", "type": "concept", "title": "Who is making the claim and why"}, {"id": "f73214f9-1771-4599-9dc7-b518165b06f8", "type": "concept", "title": "Source, sample, and method"}, {"id": "76877bee-46d1-4c2e-ae80-f81f6eca2b82", "type": "concept", "title": "Comparison group and baseline"}, {"id": "803b3ad8-27d6-4ed4-94d1-e207a29fc7be", "type": "concept", "title": "What the number does not say"}], "description": "Students identify the claim, evidence, and inference in public arguments."}, {"id": "a0decde7-09f4-44f7-afe7-0a51b05e87e4", "type": "subtopic", "title": "Science and Health Claims", "children": [{"id": "2c1b9a8a-5a94-4e35-bf71-f45b2d6abed0", "type": "concept", "title": "Correlation, causation, and experiments"}, {"id": "cef57b6f-e8d5-4a0b-a607-7e223dfc79f9", "type": "concept", "title": "Risk, screening, and treatment effects"}, {"id": "6b8d2599-5240-4fba-9efb-ce41cee96622", "type": "concept", "title": "Peer review and replication"}, {"id": "a77444f6-35b9-4eef-8737-f366b00b6c22", "type": "concept", "title": "Statistical versus clinical importance"}], "description": "Students learn to interpret studies without overclaiming."}, {"id": "89f65405-5d15-4744-aa52-b045bfc2ac95", "type": "subtopic", "title": "Policy and Civic Claims", "children": [{"id": "b1990e91-ba5d-464e-87ff-3043717cffd0", "type": "concept", "title": "Budgets, taxes, crime, education, climate, and inequality data"}, {"id": "efb9f0a4-7418-4c87-8740-78d6228bd1dc", "type": "concept", "title": "Rates versus counts"}, {"id": "0891ff43-9815-4fcd-931b-0a656eb4b81d", "type": "concept", "title": "Per-capita and inflation-adjusted comparisons"}, {"id": "8f883a42-f602-4c1d-ba34-7b1059063c7d", "type": "concept", "title": "Equity, distribution, and subgroup analysis"}], "description": "Students practice evaluating numbers used in civic decisions."}]}, {"id": "e0e0bcbd-7660-47b5-9e36-678ac4fcc4e6", "type": "topic", "title": "Personal, Civic, and Ethical Numeracy", "description": "This section asks what quantitative reasoning is for. Students connect numeracy to personal agency, democratic participation, and ethical responsibility.", "children": [{"id": "158cdc03-86d7-4097-86f2-4037b15d47b1", "type": "subtopic", "title": "Personal Quantitative Agency", "children": [{"id": "cd01c336-db32-4cdd-ad81-f6ce68c6813f", "type": "concept", "title": "Budgeting and cash flow"}, {"id": "0bd205f4-216a-4139-8561-7b820090dd35", "type": "concept", "title": "Health metrics and risk"}, {"id": "91d18bfe-7499-4cf6-974e-ddce177b040c", "type": "concept", "title": "Time, productivity, and opportunity costs"}, {"id": "e5e492f0-199c-4b44-9465-098deeffa47e", "type": "concept", "title": "Consumer decisions and warranties"}], "description": "Students use math to make practical life decisions."}, {"id": "01b6b93f-e3d5-4075-800a-fd9a1e6e3f27", "type": "subtopic", "title": "Civic Numeracy", "children": [{"id": "6ef18128-5aee-4afa-8166-d517788442d3", "type": "concept", "title": "Voting data and polling"}, {"id": "344fc4c4-715b-4c01-b1b2-568df94deb39", "type": "concept", "title": "Public budgets and debt"}, {"id": "aa565fda-fc80-4431-b582-bbfe18f59600", "type": "concept", "title": "Climate indicators and energy units"}, {"id": "5daa6941-77c9-4107-a7ed-212910325f42", "type": "concept", "title": "Inequality metrics and distributions"}], "description": "Students learn to use public data without being overwhelmed by it."}, {"id": "74487f66-53d2-4516-8a08-ae2594cea113", "type": "subtopic", "title": "Ethics and Limits of Numbers", "children": [{"id": "7e9be6b5-b8da-493c-bb52-2e987e62434b", "type": "concept", "title": "Quantification and human values"}, {"id": "4aaa4603-320f-4423-8a84-c59897b6ba8a", "type": "concept", "title": "Algorithmic decision-making"}, {"id": "4c16acaa-eba3-4e17-8900-5ea1dc978fb0", "type": "concept", "title": "Privacy and surveillance"}, {"id": "9d77557b-78f6-47f1-a2cc-cae3aa45c6ec", "type": "concept", "title": "When qualitative evidence is essential"}], "description": "Students consider what numbers can illuminate and what they can erase."}]}, {"id": "450eaa83-4a27-413f-afca-dc12665bdcac", "type": "topic", "title": "Communicating Quantitative Evidence", "description": "Students learn that good analysis must be explainable. The goal is clear, honest communication for non-specialist audiences.", "children": [{"id": "148c5a7c-4bda-4ee4-ad27-d2157b41608b", "type": "subtopic", "title": "Writing With Numbers", "children": [{"id": "4bc21ecf-166f-46b3-918d-daa628462bb5", "type": "concept", "title": "Claim-evidence-reasoning structure"}, {"id": "fc172eb5-94ae-428d-a366-f9a1447bd78b", "type": "concept", "title": "Clear definitions and units"}, {"id": "1d712b5f-694b-4ab3-8c39-73df5aeff92c", "type": "concept", "title": "Rounding and significant figures for readers"}, {"id": "6c8b74ea-4075-4767-9346-4b6685d8ac33", "type": "concept", "title": "Explaining uncertainty and limitations"}], "description": "Students practice integrating numbers into prose."}, {"id": "a0016209-59c9-4f19-8090-e0e1867efd3b", "type": "subtopic", "title": "Presenting Data Visually", "children": [{"id": "d3984d8c-57e9-4d4d-8684-8e8d43071e15", "type": "concept", "title": "Choosing chart types"}, {"id": "63a096e3-e0e9-4579-b5d7-251001733064", "type": "concept", "title": "Annotation and narrative flow"}, {"id": "2d3b4619-bc89-4050-8522-ca54cfae5f68", "type": "concept", "title": "Accessibility and color choices"}, {"id": "1e219254-ce51-4f2f-b51a-562adeb20a1f", "type": "concept", "title": "Avoiding misleading visual emphasis"}], "description": "Students design visuals that serve an argument."}, {"id": "e56e05d1-e54b-456e-abe9-f79a851dc4f6", "type": "subtopic", "title": "Speaking and Defending Findings", "children": [{"id": "abe0bc9a-a43e-4f17-940e-82287a2c5773", "type": "concept", "title": "Executive summaries and briefings"}, {"id": "22a328c5-9b7a-433c-a3f2-cce5158d393b", "type": "concept", "title": "Anticipating objections"}, {"id": "59cbc816-bde3-45fd-9488-28a7e86374a4", "type": "concept", "title": "Answering questions about assumptions"}, {"id": "98c41d28-80ed-4f1d-bfb2-c10130176266", "type": "concept", "title": "Revising after feedback"}], "description": "Students learn to discuss quantitative work in public."}]}, {"id": "de75445a-1993-45ef-ab00-c722253f8515", "type": "topic", "title": "Capstone: Model, Analyze, and Critique a Real-World Problem", "description": "The capstone synthesizes the course. Students choose a real issue, gather or use data, build a simple model, interpret results, and communicate a defensible conclusion.", "children": [{"id": "9875e1fb-6629-4822-93bc-a51ecfaca0b9", "type": "subtopic", "title": "Project Design", "children": [{"id": "a81c2901-3745-471b-b6a7-f4d98e97888d", "type": "concept", "title": "Research question and scope"}, {"id": "1d1e7e7d-48f4-4c9d-9db9-f83c79297864", "type": "concept", "title": "Data source and measurement plan"}, {"id"